    }

    spec fn shift(p: Seq<bool>, t: nat) -> Seq<bool> {
        zeroes(t).add(p)
    }

    spec fn xor(p: Seq<bool>, q: Seq<bool>) -> Seq<bool> {
        recommends(p.len() == q.len());
        Seq::new(p.len(), |i| p.index(i) ^ q.index(i))
    }

    spec fn mod_F2_X(p: Seq<bool>, q: Seq<bool>) -> Seq<bool>
        recommends
            q.len() > 0,
