        //recommends_by(mod_F2_X_rec);
        if p.len() <= (q.len() - 1) as nat {
            p.add(zeroes((q.len() - 1 - p.len()) as nat))
        } else {
            if p.last() {
                mod_F2_X(xor(p, shift(q, (p.len() - q.len()) as nat)).subrange(0, p.len() - 1), q)
            } else {
                mod_F2_X(p.subrange(0, p.len() - 1), q)
            }
        }
    }

