                (PEAExp::Dynamic { a: a1 }, PEAExp::Static { n: n2 }) =>
                    PEAExp::Dynamic { a: AExp::APlus { a1: Box::new(a1), a2: Box::new(AExp::ANum { n: n2 }) } },
                (PEAExp::Dynamic { a: a1 }, PEAExp::Dynamic { a: a2 }) =>
                    PEAExp::Dynamic { a: AExp::APlus { a1: Box::new(a1), a2: Box::new(a2) } },
