        BExp::BLe { a1, a2 } => {
            match (pe_aexp(st, a1), pe_aexp(st, a2)) {
                (PEAExp::Static { n: n1 }, PEAExp::Static { n: n2 }) =>
                    PEBExp::Static { b: n1 <= n2 },
                _ => PEBExp::Dynamic { b },
